<script setup>
import { computed, ref, onMounted, onUnmounted } from 'vue'
import { BarChart3, Download, CalendarDays, CheckCircle2, XCircle, Wallet, CarFront } from 'lucide-vue-next'
import { readData } from '../services/storage'
import { money } from '../services/fareService'
const tick=ref(0), data=computed(()=>{tick.value;return readData()})
const total=computed(()=>data.value.bookings.length), completed=computed(()=>data.value.bookings.filter(b=>b.status==='Completed').length), cancelled=computed(()=>data.value.bookings.filter(b=>b.status==='Cancelled').length)
const paid=computed(()=>data.value.payments.filter(p=>p.status==='Paid').reduce((s,p)=>s+Number(p.amount),0))
const byStatus=computed(()=>['Pending','Confirmed','In Progress','Completed','Cancelled'].map(status=>({status,count:data.value.bookings.filter(b=>b.status===status).length})))
const maxStatus=computed(()=>Math.max(1,...byStatus.value.map(x=>x.count)))
const byMonth=computed(()=>{const months=[];for(let i=5;i>=0;i--){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;months.push({key,label:d.toLocaleDateString('en',{month:'short'}),count:data.value.bookings.filter(b=>b.createdAt?.slice(0,7)===key).length,revenue:data.value.payments.filter(p=>p.status==='Paid'&&p.paidAt?.slice(0,7)===key).reduce((s,p)=>s+Number(p.amount),0)})}return months})
const maxMonth=computed(()=>Math.max(1,...byMonth.value.map(x=>x.count)))
const refresh=()=>tick.value++
onMounted(()=>window.addEventListener('taxigo:data-updated',refresh));onUnmounted(()=>window.removeEventListener('taxigo:data-updated',refresh))
function exportCsv(){const rows=[['Booking code','Passenger','Pickup','Destination','Scheduled at','Passengers','Estimated km','Fare PHP','Status'],...data.value.bookings.map(b=>[b.code,b.passengerName,b.pickup,b.destination,b.scheduledAt,b.passengers,b.estimatedKm,b.fare,b.status])];const csv=rows.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='taxigo-booking-report.csv';a.click();URL.revokeObjectURL(url)}
</script>
<template><div class="page-heading"><div><div class="eyebrow">INSIGHTS & PERFORMANCE</div><h1>Reports & analytics</h1><p>A snapshot of booking activity, ride outcomes, and recorded revenue.</p></div><button class="btn btn-primary" @click="exportCsv"><Download :size="17"/> Export bookings CSV</button></div><div class="report-kpis"><article><span class="report-kpi-icon blue"><CalendarDays/></span><small>Total bookings</small><strong>{{total}}</strong><span class="muted">All time</span></article><article><span class="report-kpi-icon green"><CheckCircle2/></span><small>Completed rides</small><strong>{{completed}}</strong><span class="muted">{{total?Math.round(completed/total*100):0}}% completion rate</span></article><article><span class="report-kpi-icon amber"><XCircle/></span><small>Cancelled rides</small><strong>{{cancelled}}</strong><span class="muted">{{total?Math.round(cancelled/total*100):0}}% cancellation rate</span></article><article><span class="report-kpi-icon violet"><Wallet/></span><small>Paid revenue</small><strong>{{money(paid)}}</strong><span class="muted">Excludes refunded records</span></article></div><div class="reports-grid"><section class="panel report-panel"><div class="panel-heading"><div><h3>Bookings by status</h3><p>Distribution of all ride requests</p></div><BarChart3 class="muted-icon"/></div><div class="bar-chart"><div v-for="s in byStatus" :key="s.status" class="bar-row"><div class="bar-label"><span>{{s.status}}</span><strong>{{s.count}}</strong></div><div class="bar-track"><div class="bar-fill" :class="s.status.toLowerCase().replace(' ','-')" :style="{width:s.count/maxStatus*100+'%'}"></div></div></div></div><div class="chart-footnote">Counts update automatically when booking statuses change.</div></section><section class="panel report-panel"><div class="panel-heading"><div><h3>Booking activity</h3><p>Created bookings over the last six months</p></div><CalendarDays class="muted-icon"/></div><div class="month-chart"><div v-for="m in byMonth" :key="m.key" class="month-column"><strong>{{m.count}}</strong><div class="month-bar-wrap"><div class="month-bar" :style="{height:Math.max(m.count?8:2,m.count/maxMonth*100)+'%'}"></div></div><span>{{m.label}}</span></div></div><div class="chart-footnote">Bars represent booking creation date, not ride date.</div></section></div><section class="panel report-panel monthly-table"><div class="panel-heading"><div><h3>Monthly summary</h3><p>Bookings and paid payment records by creation/payment month</p></div></div><div class="table-wrap"><table><thead><tr><th>MONTH</th><th>BOOKINGS</th><th>COMPLETED</th><th>CANCELLED</th><th>PAID REVENUE</th></tr></thead><tbody><tr v-for="m in byMonth" :key="m.key"><td><strong>{{m.label}} {{m.key.slice(0,4)}}</strong></td><td>{{m.count}}</td><td>{{data.bookings.filter(b=>b.createdAt?.slice(0,7)===m.key&&b.status==='Completed').length}}</td><td>{{data.bookings.filter(b=>b.createdAt?.slice(0,7)===m.key&&b.status==='Cancelled').length}}</td><td><strong>{{money(m.revenue)}}</strong></td></tr></tbody></table></div></section><p class="report-disclaimer">Reports are based on records stored in this browser. Paid revenue reflects current payment statuses and is intended for educational demonstration.</p></template>